// Generated by tour2playwright from a Tour Recorder export, then hand-edited.
// Source tour: Finance: Record a Ledger Budget - Income & Expense Accounts (Full Flow)
// Hand edits: real values typed in the `edit` steps, label/field-name selectors, state assertions, result screenshots,
// wide viewport, login fallback, cleanup of the records this run creates.
// WRITES (test database only): creates two budgetary positions and one budget (then confirms it).
// Everything is tagged [TEST] and removed again afterwards.
import { test, expect } from "../../../../core/fixtures/index";
import { uniqueName } from "../../../../core/utils/RandomDataGenerator";
import type { Page, Locator } from "@playwright/test";
import fs from "node:fs";

const SHOT_DIR = "tools/tour2playwright/generated/screenshots/finance-record-a-ledger-budget-income-expense-accounts-full-flow";
const REV_POS = uniqueName("FY2028 Revenue - Ledger Budget");
const RUN_TAG = REV_POS.split(" ").pop() as string;
const EXP_POS = `[TEST] FY2028 Operating Expenses - Ledger Budget ${RUN_TAG}`;
const BUDGET = `[TEST] Budget 2028 - Ledger (Income & Expense) ${RUN_TAG}`;

// A step's own screenshot is taken BEFORE its action; this keeps one of the finished screen.
async function resultShot(page: Page, n: number) {
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  await page.screenshot({ path: `${SHOT_DIR}/step-${String(n).padStart(2, "0")}-result.png` });
}

// Screenshot the current page with the target element outlined.
async function shot(page: Page, loc: Locator, file: string) {
  try {
    await loc.scrollIntoViewIfNeeded({ timeout: 5000 });
    await loc.evaluate((el) => el.setAttribute("data-t2p", "1"));
    await page.addStyleTag({
      content: '[data-t2p="1"]{outline:3px solid #e01e5a !important;outline-offset:2px !important;}',
    });
  } catch {}
  fs.mkdirSync(SHOT_DIR, { recursive: true });
  await page.screenshot({ path: `${SHOT_DIR}/${file}` });
  try { await loc.evaluate((el) => el.removeAttribute("data-t2p")); } catch {}
}

test.describe("Finance: Record a Ledger Budget - Income & Expense Accounts (Full Flow) @module:accounting @step:business @e2e", () => {
  // At the default 1280px some top-menu entries collapse into the "+" overflow.
  test.use({ viewport: { width: 1600, height: 900 } });

  // Remove what this run created (a confirmed budget has to be cancelled before it can be deleted).
  test.afterEach(async ({ rpc }) => {
    const budgets = await rpc.searchRead<{ id: number }>("crossovered.budget", [["name", "like", RUN_TAG]], ["id"]).catch(() => []);
    if (budgets.length) await rpc.write("crossovered.budget", budgets.map((b) => b.id), { state: "cancel" }).catch(() => {});
    if (budgets.length) await rpc.unlink("crossovered.budget", budgets.map((b) => b.id)).catch(() => {});
    const posts = await rpc.searchRead<{ id: number }>("account.budget.post", [["name", "like", RUN_TAG]], ["id"]).catch(() => []);
    if (posts.length) await rpc.unlink("account.budget.post", posts.map((p) => p.id)).catch(() => {});
  });

  test("Finance: Record a Ledger Budget - Income & Expense Accounts (Full Flow)", async ({ page, rpc }) => {
    test.setTimeout(420_000);
    await page.goto("/web");

    // The rpc fixture's API login can end the saved browser session — fall back to the login form.
    const emailBox = page.getByRole("textbox", { name: "Email" });
    if (await emailBox.isVisible({ timeout: 8_000 }).catch(() => false)) {
      await emailBox.fill(process.env.ADMIN_EMAIL ?? "admin");
      await page.getByRole("textbox", { name: "Password" }).fill(process.env.ADMIN_PASSWORD ?? "admin");
      await page.getByRole("button", { name: "Log in" }).click();
      await page.waitForSelector(".o_main_navbar, .o_home_menu", { state: "visible", timeout: 45_000 });
    }
    await page.waitForLoadState("networkidle", { timeout: 10_000 }).catch(() => {});

    const run = async (n: number, title: string, loc: Locator, act?: (l: Locator) => Promise<void>, result = false) => {
      await test.step(`${String(n).padStart(2, "0")}. ${title}`, async () => {
        const l = loc.first();
        await l.waitFor({ state: "visible", timeout: 45000 });
        await shot(page, l, `step-${String(n).padStart(2, "0")}.png`);
        if (act) await act(l);
        if (result) await resultShot(page, n);
      });
    };
    const menu = (xmlid: string) => page.locator(`[data-menu-xmlid="${xmlid}"]`);
    const topMenu = (name: string) => page.locator(".o_menu_sections .dropdown-toggle, .o_menu_sections > a").filter({ hasText: new RegExp(`^${name}$`) });
    const newBtn = page.getByRole("button", { name: "New", exact: true });
    const nameInput = page.locator('.o_form_view div[name="name"] input');
    const modal = page.locator(".modal:visible");
    const modalSearch = modal.locator(".o_searchview_input");
    const addLine = page.locator("td.o_field_x2many_list_row_add a");
    const saveBtn = page.locator("button.o_form_button_save");
    const saved = async (what: string) => expect(saveBtn, `${what} saved`).toBeHidden({ timeout: 30000 });

    // Search the account picker. Once an account is ticked Odoo HIDES the picker's search box, so the recorded
    // "remove the facet and search again" is replaced: search a shared prefix once and tick both accounts from it.
    const searchAccount = async (n: number, prefix: string, code: string) => {
      await run(n, `Type ${code} in the search box`, modalSearch, async (l) => { await l.fill(prefix); });
      await run(n + 1, "Press Enter to run the search", modalSearch, async (l) => {
        await l.press("Enter");
        await expect(modal.locator(".o_data_row").filter({ hasText: code }).first(), `account ${code} found`).toBeVisible({ timeout: 20000 });
      });
    };
    const tickFirst = (n: number, code: string) =>
      run(n, `Tick the checkbox on ${code}`, modal.locator(".o_data_row").filter({ hasText: code }).first().locator(".o_list_record_selector input"), async (l) => {
        await l.check();
        await expect(l).toBeChecked();
      }, true);
    // Steps that, in the recording, cleared the facet and searched for the second account.
    const secondAccount = async (n: number, code: string) => {
      await run(n, "The ticked account stays selected", modal.locator(".o_selection_badge, .o_list_selection_box").first(), async (l) => {
        await expect(l).toContainText(/1 selected|selected/i);
      }, true);
      await run(n + 1, `Find ${code} in the same list`, modal.locator(".o_data_row").filter({ hasText: code }).first(), async (l) => {
        await expect(l).toBeVisible();
      });
      await run(n + 2, `Check ${code} is listed`, modal.locator(".o_data_row").filter({ hasText: code }).first(), async (l) => {
        await expect(l).toContainText(code);
      });
    };
    const selectBtn = (n: number) =>
      run(n, "Click Select", modal.locator("footer button.o_select_button"), async (l) => {
        await l.click();
        await expect(modal, "picker closed").toBeHidden({ timeout: 20000 });
      }, true);

    // ------------------------------------------------------------------ Part 1: the revenue position
    await run(1, "Open the Accounting app", menu("account_accountant.menu_accounting"), (l) => l.click());
    await run(2, "Open the Configuration menu", topMenu("Configuration"), (l) => l.click(), true);
    await run(3, "Click Budgetary Positions", menu("account_budget.menu_budget_post_form"), async (l) => {
      await l.click();
      await expect(page.locator(".o_list_view"), "Budgetary Positions list opened").toBeVisible({ timeout: 30000 });
    }, true);
    await run(4, "Click New (income position)", newBtn, async (l) => {
      await l.click();
      await expect(nameInput, "new position form opened").toBeVisible({ timeout: 30000 });
    }, true);
    await run(5, "Type the position name", nameInput, async (l) => { await l.fill(REV_POS); await expect(l).toHaveValue(REV_POS); }, true);
    await run(6, "Add a line", addLine, async (l) => {
      await l.click();
      await expect(modal, "account picker opened").toBeVisible({ timeout: 20000 });
    }, true);
    await searchAccount(7, "41010", "41010010");
    await tickFirst(9, "41010010");
    await secondAccount(10, "41010050");
    await tickFirst(13, "41010050");
    await selectBtn(14);
    await run(15, "Save the position", saveBtn, async (l) => {
      await expect(page.locator(".o_form_view"), "both revenue accounts are in the position").toContainText(/41010010/);
      await expect(page.locator(".o_form_view")).toContainText(/41010050/);
      await l.click();
      await saved("revenue position");
    }, true);

    // ------------------------------------------------------------------ Part 2: the expense position
    await run(16, "Back to Budgetary Positions", page.locator(".o_back_button, .breadcrumb-item").filter({ hasText: /Budgetary Positions/ }), async (l) => {
      await l.click();
      await expect(page.locator(".o_list_view")).toBeVisible({ timeout: 30000 });
    }, true);
    await run(17, "Click New (expense position)", newBtn, async (l) => {
      await l.click();
      await expect(nameInput).toBeVisible({ timeout: 30000 });
    }, true);
    await run(18, "Type the position name", nameInput, async (l) => { await l.fill(EXP_POS); await expect(l).toHaveValue(EXP_POS); }, true);
    await run(19, "Add a line", addLine, async (l) => {
      await l.click();
      await expect(modal).toBeVisible({ timeout: 20000 });
    }, true);
    await searchAccount(20, "510", "51010010");
    await tickFirst(22, "51010010");
    await secondAccount(23, "51050010");
    await tickFirst(26, "51050010");
    await selectBtn(27);
    await run(28, "Save the position", saveBtn, async (l) => {
      await expect(page.locator(".o_form_view")).toContainText(/51010010/);
      await expect(page.locator(".o_form_view")).toContainText(/51050010/);
      await l.click();
      await saved("expense position");
    }, true);

    // ------------------------------------------------------------------ Part 3: the budget
    await run(29, "Open the Accounting menu", topMenu("Accounting"), (l) => l.click(), true);
    await run(30, "Click Budgets", menu("account_budget.menu_act_crossovered_budget_view"), async (l) => {
      await l.click();
      await expect(page.locator(".o_list_view"), "Budgets list opened").toBeVisible({ timeout: 30000 });
    }, true);
    await run(31, "Click New (budget)", newBtn, async (l) => {
      await l.click();
      await expect(nameInput).toBeVisible({ timeout: 30000 });
    }, true);
    await run(32, "Budget Name", nameInput, async (l) => { await l.fill(BUDGET); await expect(l).toHaveValue(BUDGET); }, true);
    await run(33, "Period start date", page.locator('div[name="date_from"] input'), async (l) => {
      await l.fill("01/01/2028"); await l.press("Tab"); await expect(l).toHaveValue("01/01/2028");
    }, true);
    await run(34, "Period end date", page.locator('div[name="date_to"] input'), async (l) => {
      await l.fill("31/12/2028"); await l.press("Tab"); await expect(l).toHaveValue("31/12/2028");
    }, true);

    // One budget line: pick the position by name, type dates and the planned amount.
    const budgetLine = async (first: number, position: string, amount: string, label: string) => {
      await run(first, `Add a line (${label})`, addLine, async (l) => {
        await l.click();
        await expect(page.locator(".o_selected_row"), "line opened").toBeVisible({ timeout: 15000 });
      }, true);
      await run(first + 1, `Budgetary Position (${label})`, page.locator('.o_selected_row td[name="general_budget_id"] input'), async (l) => {
        await l.click();
        await l.fill(position.slice(0, 40));
        const opt = page.locator(".o-autocomplete--dropdown-item").filter({ hasText: RUN_TAG }).first();
        await opt.waitFor({ state: "visible", timeout: 15000 });
        await opt.click();
        await expect(l).toHaveValue(new RegExp(RUN_TAG));
      }, true);
      await run(first + 2, `Line start date (${label})`, page.locator('.o_selected_row td[name="date_from"] input'), async (l) => {
        await l.fill("01/01/2028"); await l.press("Tab");
      }, true);
      await run(first + 3, `Line end date (${label})`, page.locator('.o_selected_row td[name="date_to"] input'), async (l) => {
        await l.fill("31/12/2028"); await l.press("Tab");
      }, true);
      await run(first + 4, `Planned Amount (${label})`, page.locator('.o_selected_row td[name="planned_amount"] input'), async (l) => {
        await l.fill(amount); // no Tab here: Tab on the last cell of the last row starts a new line
      }, true);
    };
    // The line's Budget column is required and cannot be filled on an unsaved budget: save the budget (still
    // without lines) so that the lines inherit it.
    await test.step("34b. Save the budget header", async () => {
      await saveBtn.click();
      await saved("budget header");
    });
    // The "Add a line" step of the second line is the tour's step 40: number the sub-steps to match it.
    await run(35, "Add a line (income)", addLine, async (l) => {
      await l.click();
      await expect(page.locator(".o_selected_row"), "line opened").toBeVisible({ timeout: 15000 });
    }, true);
    const fillLine = async (n0: number, position: string, amount: string, label: string) => {
      await run(n0, `Budgetary Position (${label})`, page.locator('.o_selected_row td[name="general_budget_id"] input'), async (l) => {
        await l.click();
        await l.fill(position);
        const opt = page.locator(".o-autocomplete--dropdown-item").filter({ hasText: RUN_TAG }).filter({ hasText: position }).first();
        await opt.waitFor({ state: "visible", timeout: 15000 });
        await opt.click();
        await expect(l).toHaveValue(new RegExp(position));
      }, true);
      await run(n0 + 1, `Line start date (${label})`, page.locator('.o_selected_row td[name="date_from"] input'), async (l) => {
        await l.fill("01/01/2028"); await l.press("Tab");
      }, true);
      await run(n0 + 2, `Line end date (${label})`, page.locator('.o_selected_row td[name="date_to"] input'), async (l) => {
        await l.fill("31/12/2028"); await l.press("Tab");
      }, true);
      await run(n0 + 3, `Planned Amount (${label})`, page.locator('.o_selected_row td[name="planned_amount"] input'), async (l) => {
        await l.fill(amount); // no Tab here: Tab on the last cell of the last row starts a new line
      }, true);
    };
    await fillLine(36, "FY2028 Revenue", "250000000", "income");
    await run(40, "Add a line (expense)", addLine, async (l) => {
      // Commit the income line first (click on a plain label outside the grid), otherwise the click only re-selects it.
      await page.locator(".o_form_view .o_form_label").first().click();
      await expect(page.locator(".o_data_row"), "income line committed").toHaveCount(1);
      await l.click();
      await expect(page.locator(".o_data_row"), "second line added").toHaveCount(2, { timeout: 15000 });
      await expect(page.locator(".o_selected_row"), "second line opened").toBeVisible({ timeout: 15000 });
    }, true);
    await fillLine(41, "FY2028 Operating", "-180000000", "expense");
    void budgetLine;

    await run(45, "Save the budget", saveBtn, async (l) => {
      await l.click();
      await saved("budget");
      const [b] = await rpc.searchRead<{ id: number }>("crossovered.budget", [["name", "=", BUDGET]], ["id"], { limit: 1 });
      expect(b, "the budget exists in the database").toBeTruthy();
      const lines = await rpc.searchRead<{ planned_amount: number }>("crossovered.budget.lines", [["crossovered_budget_id", "=", b.id]], ["planned_amount"]);
      expect(lines.map((x) => x.planned_amount).sort((a, c) => a - c), "both planned amounts were saved").toEqual([-180000000, 250000000]);
    }, true);
    await run(46, "Read the computed columns", page.locator('.o_field_x2many table thead th[data-name="practical_amount"]'), async (l) => {
      await expect(l).toBeVisible();
      await expect(page.locator('.o_field_x2many table thead th[data-name="theoritical_amount"]')).toBeVisible();
    });
    await run(47, "Confirm the budget", page.locator('button[name="action_budget_confirm"]'), async (l) => {
      await l.click();
      await expect(page.locator(".o_statusbar_status .o_arrow_button_current"), "budget is Confirmed").toContainText(/Confirmed/i, { timeout: 30000 });
    }, true);

    // ------------------------------------------------------------------ Part 4: the analysis report
    await run(48, "Open the Reporting menu", topMenu("Reporting"), (l) => l.click(), true);
    await run(49, "Click Budgets Analysis", menu("account_budget.menu_act_crossovered_budget_lines_view"), async (l) => {
      await l.click();
      // The budget form's own line list is also an ".o_list_view", so wait for the form to be gone first.
      await expect(page.locator(".o_form_view"), "left the budget form").toHaveCount(0, { timeout: 30000 });
      await expect(page.locator(".o_list_view, .o_pivot, .o_graph_renderer").first(), "analysis opened").toBeVisible({ timeout: 30000 });
      await expect(page.locator(".o_group_header").filter({ hasText: RUN_TAG }), "the new budget is in the analysis").toBeVisible({ timeout: 30000 });
    }, true);
  });
});
